export type VillagePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function villageProgram(
  config: { programAddress?: Address | HasAddress } = {},
) {
  return <T extends VillagePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { village: VillagePlugin }> => {
    return extendClient(client, {
      village: <VillagePlugin>{
        accounts: {
          contestant: addSelfFetchFunctions(client, getContestantCodec()),
          match: addSelfFetchFunctions(client, getMatchCodec()),
        },
        instructions: {
          accept: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          advanceDay: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdvanceDayInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          bid: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getBidInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          build: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuildInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeMatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseMatchInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeTable: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseTableInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createMatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMatchInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          finalizeMatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getFinalizeMatchInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          joinMatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getJoinMatchInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          registerChild: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterChildInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          registerFounder: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterFounderInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          reject: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRejectInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          rest: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRestInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          say: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSayInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          show: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getShowInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          startMatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getStartMatchInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          travel: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getTravelInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          work: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWorkInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
        },
        pdas: {
          game: (seeds, pdaConfig) =>
            findGamePda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          contestant: (seeds, pdaConfig) =>
            findContestantPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          parent: (seeds, pdaConfig) =>
            findParentPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyVillageAccount,
        identifyInstruction: identifyVillageInstruction,
        parseInstruction: parseVillageInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
